insert into public.ew_words
  (term, pos, ipa, translation_uk, definition_en, example_en, topics, level, sort_order)
values
  ('contract', 'noun', '/ˈkɒntrækt/', 'договір, контракт', 'A legally binding agreement between two or more parties.', 'Both parties signed the contract before the deadline.', array['contract'], 'B1', 1),
  ('agreement', 'noun', '/əˈɡriːmənt/', 'угода, домовленість', 'An arrangement between people about what each will do.', 'They reached an agreement after a long negotiation.', array['contract'], 'B1', 2),
  ('party', 'noun', '/ˈpɑːti/', 'сторона (договору, справи)', 'A person or group involved in a contract or legal case.', 'Each party must receive a copy of the document.', array['contract','procedure'], 'B1', 3),
  ('clause', 'noun', '/klɔːz/', 'пункт, застереження', 'A separate section of a contract or law.', 'The clause limits the seller''s responsibility.', array['contract'], 'B1', 4),
  ('term', 'noun', '/tɜːm/', 'умова; строк', 'A condition of an agreement, or a period of time.', 'The term of the lease is twelve months.', array['contract'], 'B1', 5),
  ('obligation', 'noun', '/ˌɒblɪˈɡeɪʃn/', 'зобов''язання', 'A duty that a person must legally perform.', 'The tenant has an obligation to pay rent on time.', array['contract'], 'B2', 6),
  ('consideration', 'noun', '/kənˌsɪdəˈreɪʃn/', 'зустрічне надання, відшкодування', 'Something of value exchanged by each party to make a contract valid.', 'Without consideration, the promise is not enforceable.', array['contract'], 'C1', 7),
  ('offer', 'noun', '/ˈɒfə/', 'оферта, пропозиція', 'A clear proposal to make a contract on stated terms.', 'She accepted the offer in writing.', array['contract'], 'B1', 8),
  ('acceptance', 'noun', '/əkˈseptəns/', 'акцепт, прийняття', 'Agreement to the terms of an offer.', 'Acceptance of the offer creates a binding contract.', array['contract'], 'B2', 9),
  ('breach', 'noun', '/briːtʃ/', 'порушення (договору)', 'A failure to keep a promise or obey a rule in a contract or law.', 'The late delivery was a serious breach of contract.', array['contract','tort'], 'B2', 10),
  ('remedy', 'noun', '/ˈremədi/', 'засіб захисту, відшкодування', 'A way the law gives to enforce a right or fix a wrong.', 'Damages are the usual remedy for breach of contract.', array['contract','procedure'], 'B2', 11),
  ('damages', 'noun', '/ˈdæmɪdʒɪz/', 'збитки, відшкодування шкоди', 'Money a court orders one party to pay for loss or harm.', 'The court awarded damages of ten thousand euros.', array['contract','tort'], 'B2', 12),
  ('enforce', 'verb', '/ɪnˈfɔːs/', 'забезпечувати виконання, примушувати', 'To make sure a law or agreement is obeyed.', 'A court can enforce the terms of the agreement.', array['contract','procedure'], 'B2', 13),
  ('void', 'adjective', '/vɔɪd/', 'недійсний', 'Having no legal effect from the beginning.', 'A contract made under threat is void.', array['contract'], 'B2', 14),
  ('voidable', 'adjective', '/ˈvɔɪdəbl/', 'оспорюваний', 'Valid until one party chooses to cancel it.', 'A contract signed by a minor may be voidable.', array['contract'], 'C1', 15),
  ('terminate', 'verb', '/ˈtɜːmɪneɪt/', 'припиняти, розривати', 'To end a contract or agreement.', 'The landlord may terminate the lease with notice.', array['contract'], 'B2', 16),
  ('rescind', 'verb', '/rɪˈsɪnd/', 'скасовувати, розривати', 'To cancel a contract and return the parties to their earlier positions.', 'He asked the court to rescind the sale.', array['contract'], 'C1', 17),
  ('waive', 'verb', '/weɪv/', 'відмовлятися (від права)', 'To voluntarily give up a right or claim.', 'The buyer waived the right to inspect the goods.', array['contract'], 'C1', 18),
  ('warranty', 'noun', '/ˈwɒrənti/', 'гарантія', 'A promise about the quality or condition of goods.', 'The car comes with a two-year warranty.', array['contract'], 'B2', 19),
  ('guarantee', 'noun', '/ˌɡærənˈtiː/', 'гарантія, поручительство', 'A promise to be responsible for a debt or duty.', 'The bank required a personal guarantee.', array['contract'], 'B2', 20),
  ('indemnify', 'verb', '/ɪnˈdemnɪfaɪ/', 'відшкодовувати збитки', 'To protect someone against loss by promising to compensate them.', 'The seller agreed to indemnify the buyer against any claims.', array['contract'], 'C1', 21),
  ('liability', 'noun', '/ˌlaɪəˈbɪləti/', 'відповідальність; зобов''язання', 'Legal responsibility for something, especially for harm or debt.', 'The company denied liability for the accident.', array['contract','tort'], 'B2', 22),
  ('party autonomy', 'noun', '/ˈpɑːti ɔːˈtɒnəmi/', 'свобода договору (автономія сторін)', 'The freedom of parties to decide the terms of their contract.', 'Party autonomy allows businesses to choose the governing law.', array['contract'], 'C1', 23),
  ('binding', 'adjective', '/ˈbaɪndɪŋ/', 'обов''язковий, який зобов''язує', 'Legally forcing people to obey or perform.', 'The decision is binding on all members.', array['contract','procedure'], 'B2', 24),
  ('deed', 'noun', '/diːd/', 'нотаріальний акт, документ', 'A signed legal document, especially about property.', 'She signed the deed in front of a witness.', array['contract','property'], 'B2', 25),
  ('draft', 'verb', '/drɑːft/', 'складати (проєкт документа)', 'To write the first version of a legal document.', 'The lawyer will draft the agreement this week.', array['contract'], 'B1', 26),
  ('sign', 'verb', '/saɪn/', 'підписувати', 'To write your name on a document to show agreement.', 'Please sign at the bottom of the page.', array['contract'], 'B1', 27),
  ('signatory', 'noun', '/ˈsɪɡnətri/', 'підписант, сторона що підписала', 'A person or state that has signed an agreement.', 'All signatories must approve any change.', array['contract'], 'C1', 28),
  ('witness', 'noun', '/ˈwɪtnəs/', 'свідок', 'A person who sees an event or signing and can say what happened.', 'A witness must sign the will.', array['contract','evidence'], 'B1', 29),
  ('capacity', 'noun', '/kəˈpæsəti/', 'дієздатність, правоздатність', 'The legal ability to make a binding decision or agreement.', 'A minor usually lacks the capacity to sign a contract.', array['contract'], 'C1', 30),
  ('consent', 'noun', '/kənˈsent/', 'згода', 'Permission or agreement given freely.', 'The patient gave informed consent to the treatment.', array['contract','criminal'], 'B2', 31),
  ('duress', 'noun', '/djʊˈres/', 'примус, тиск', 'Unlawful pressure that forces someone to act against their will.', 'He signed the paper under duress.', array['contract','criminal'], 'C1', 32),
  ('misrepresentation', 'noun', '/ˌmɪsreprɪzenˈteɪʃn/', 'введення в оману, викривлення фактів', 'A false statement that persuades someone to make a contract.', 'The buyer sued for misrepresentation of the car''s history.', array['contract'], 'C1', 33),
  ('fraud', 'noun', '/frɔːd/', 'шахрайство', 'Deliberate deception to get money or advantage.', 'He was charged with fraud after forging the invoices.', array['contract','criminal'], 'B2', 34),
  ('default', 'noun', '/dɪˈfɔːlt/', 'невиконання зобов''язань, дефолт', 'Failure to pay a debt or do what an agreement requires.', 'The borrower is in default on the loan.', array['contract'], 'B2', 35),
  ('penalty', 'noun', '/ˈpenlti/', 'штраф, санкція', 'A punishment or extra payment for breaking a rule or contract.', 'The contract includes a penalty for late payment.', array['contract','criminal'], 'B1', 36),
  ('lease', 'noun', '/liːs/', 'оренда, договір оренди', 'A contract allowing someone to use property in exchange for rent.', 'They signed a five-year lease on the office.', array['contract','property'], 'B2', 37),
  ('tenant', 'noun', '/ˈtenənt/', 'орендар, наймач', 'A person who pays rent to use a property.', 'The tenant must report any repairs.', array['property','contract'], 'B1', 38),
  ('landlord', 'noun', '/ˈlændlɔːd/', 'орендодавець, власник житла', 'A person who owns property and rents it to others.', 'The landlord raised the rent this year.', array['property','contract'], 'B1', 39),
  ('arbitration', 'noun', '/ˌɑːbɪˈtreɪʃn/', 'арбітраж', 'Settling a dispute by a neutral person instead of a court.', 'The parties agreed to resolve disputes by arbitration.', array['contract','procedure'], 'C1', 40),
  ('mediation', 'noun', '/ˌmiːdiˈeɪʃn/', 'медіація', 'Helping opposing sides reach an agreement without a trial.', 'Mediation saved both sides time and money.', array['contract','procedure'], 'C1', 41),
  ('settle', 'verb', '/ˈsetl/', 'врегулювати, домовитися мирно', 'To end a dispute by agreement.', 'The parties decided to settle before trial.', array['contract','procedure'], 'B2', 42),
  ('settlement', 'noun', '/ˈsetlmənt/', 'мирова угода, врегулювання', 'An official agreement that ends a legal dispute.', 'The settlement was approved by the judge.', array['contract','procedure'], 'B2', 43),
  ('tort', 'noun', '/tɔːt/', 'делікт, цивільне правопорушення', 'A civil wrong that causes harm and gives the victim a right to compensation.', 'Negligence is the most common tort.', array['tort'], 'B2', 44),
  ('negligence', 'noun', '/ˈneɡlɪdʒəns/', 'недбалість, халатність', 'Failure to take reasonable care, causing harm to another.', 'The hospital was sued for medical negligence.', array['tort'], 'B2', 45),
  ('duty of care', 'noun', '/ˈdjuːti əv keə/', 'обов''язок обачності', 'A legal duty to avoid causing harm to others.', 'Drivers owe a duty of care to other road users.', array['tort'], 'C1', 46),
  ('reasonable', 'adjective', '/ˈriːznəbl/', 'розумний, обґрунтований', 'Fair, sensible and what an ordinary person would expect.', 'He took all reasonable steps to avoid the risk.', array['tort','general'], 'B1', 47),
  ('foreseeable', 'adjective', '/fɔːˈsiːəbl/', 'передбачуваний', 'Able to be expected or predicted.', 'The injury was a foreseeable result of the delay.', array['tort'], 'C1', 48),
  ('causation', 'noun', '/kɔːˈzeɪʃn/', 'причинний зв''язок', 'The link between an act and the harm it caused.', 'The claimant must prove causation.', array['tort','criminal'], 'C1', 49),
  ('harm', 'noun', '/hɑːm/', 'шкода', 'Physical or emotional damage or injury.', 'The law protects people from serious harm.', array['tort','criminal'], 'B1', 50),
  ('injury', 'noun', '/ˈɪndʒəri/', 'тілесне ушкодження, травма', 'Physical damage to a person''s body.', 'She suffered a back injury at work.', array['tort','criminal'], 'B1', 51),
  ('loss', 'noun', '/lɒs/', 'збиток, втрата', 'Money or value that a person no longer has.', 'The firm claimed compensation for its financial loss.', array['tort','contract'], 'B1', 52),
  ('compensation', 'noun', '/ˌkɒmpenˈseɪʃn/', 'компенсація', 'Money paid to make up for harm or loss.', 'The victim received compensation for lost wages.', array['tort','contract'], 'B2', 53),
  ('claimant', 'noun', '/ˈkleɪmənt/', 'позивач (у Британії), заявник', 'A person who starts a civil claim in court.', 'The claimant asked for damages and legal costs.', array['tort','procedure'], 'B2', 54),
  ('victim', 'noun', '/ˈvɪktɪm/', 'потерпілий, жертва', 'A person harmed by a crime or accident.', 'The victim gave a statement to the police.', array['tort','criminal'], 'B1', 55),
  ('nuisance', 'noun', '/ˈnjuːsns/', 'неприємність, порушення спокою', 'Something that unreasonably disturbs the use of land or public rights.', 'Loud music at night can be a private nuisance.', array['tort','property'], 'C1', 56),
  ('trespass', 'noun', '/ˈtrespəs/', 'порушення меж власності', 'Entering another person''s land or property without permission.', 'He was charged with trespass for crossing the fence.', array['tort','property'], 'C1', 57),
  ('defamation', 'noun', '/ˌdefəˈmeɪʃn/', 'наклеп, дифамація', 'Harming a person''s reputation with false statements.', 'The politician sued the paper for defamation.', array['tort'], 'C1', 58),
  ('libel', 'noun', '/ˈlaɪbl/', 'наклеп (письмовий)', 'A false written statement that damages someone''s reputation.', 'The article was found to be libel.', array['tort'], 'C1', 59),
  ('slander', 'noun', '/ˈslɑːndə/', 'наклеп (усний)', 'A false spoken statement that damages someone''s reputation.', 'She sued him for slander after his speech.', array['tort'], 'C1', 60),
  ('strict liability', 'noun', '/strɪkt ˌlaɪəˈbɪləti/', 'відповідальність без вини', 'Responsibility for harm even without fault or intent.', 'Producers face strict liability for dangerous products.', array['tort','contract'], 'C1', 61),
  ('vicarious liability', 'noun', '/vɪˈkeəriəs ˌlaɪəˈbɪləti/', 'відповідальність за іншу особу', 'Responsibility of one person for the wrong done by another, such as an employee.', 'The employer has vicarious liability for its staff.', array['tort'], 'C1', 62),
  ('contributory negligence', 'noun', '/kənˈtrɪbjətri ˈneɡlɪdʒəns/', 'власна необережність потерпілого', 'Partial fault of the injured person that reduces compensation.', 'His compensation was cut for contributory negligence because he wore no seat belt.', array['tort'], 'C1', 63),
  ('defence', 'noun', '/dɪˈfens/', 'захист; заперечення', 'Arguments or evidence that a person is not liable or guilty.', 'Self-defence is a complete defence to the charge.', array['tort','criminal','procedure'], 'B2', 64),
  ('fault', 'noun', '/fɔːlt/', 'вина, провина', 'Responsibility for a mistake or wrong.', 'The court found the driver at fault.', array['tort'], 'B1', 65),
  ('intention', 'noun', '/ɪnˈtenʃn/', 'умисел, намір', 'A planned purpose to do something.', 'Intention is an important element of many crimes.', array['tort','criminal'], 'B2', 66),
  ('recklessness', 'noun', '/ˈrekləsnəs/', 'безрозсудність', 'Taking a serious risk without caring about the result.', 'The judge described his behaviour as recklessness.', array['tort','criminal'], 'C1', 67),
  ('mitigate', 'verb', '/ˈmɪtɪɡeɪt/', 'пом''якшувати, зменшувати наслідки', 'To make harm or loss less serious.', 'The claimant must mitigate his loss where possible.', array['tort','contract'], 'C1', 68),
  ('restitution', 'noun', '/ˌrestɪˈtjuːʃn/', 'реституція, повернення', 'Returning something to its owner or paying for its value.', 'The court ordered restitution of the stolen funds.', array['contract','tort'], 'C1', 69),
  ('injunction', 'noun', '/ɪnˈdʒʌŋkʃn/', 'судова заборона', 'A court order requiring someone to do or stop doing something.', 'The court granted an injunction against the publication.', array['tort','procedure'], 'C1', 70),
  ('specific performance', 'noun', '/spəˌsɪfɪk pəˈfɔːməns/', 'реальне виконання зобов''язання', 'A court order to carry out a contract instead of paying damages.', 'He sought specific performance of the sale of the land.', array['contract'], 'C1', 71),
  ('unjust enrichment', 'noun', '/ʌnˈdʒʌst ɪnˈrɪtʃmənt/', 'безпідставне збагачення', 'Unfairly gaining benefit at another person''s expense.', 'The claim for unjust enrichment succeeded.', array['contract','tort'], 'C1', 72),
  ('crime', 'noun', '/kraɪm/', 'злочин', 'An act that breaks the criminal law.', 'Theft is a crime in every country.', array['criminal'], 'B1', 73),
  ('offence', 'noun', '/əˈfens/', 'правопорушення', 'An illegal act that can be punished.', 'Driving without a licence is an offence.', array['criminal'], 'B2', 74),
  ('felony', 'noun', '/ˈfeləni/', 'тяжкий злочин (США)', 'A serious crime such as murder or robbery.', 'He was convicted of a felony and sent to prison.', array['criminal'], 'C1', 75),
  ('misdemeanour', 'noun', '/ˌmɪsdɪˈmiːnə/', 'проступок, злочин невеликої тяжкості', 'A minor crime with a lighter punishment.', 'Petty theft is usually a misdemeanour.', array['criminal'], 'C1', 76),
  ('theft', 'noun', '/θeft/', 'крадіжка', 'The crime of taking someone else''s property without permission.', 'The theft of the laptop was reported to the police.', array['criminal'], 'B1', 77),
  ('robbery', 'noun', '/ˈrɒbəri/', 'грабіж, розбій', 'Stealing from a person using force or threat.', 'Two men were arrested for armed robbery.', array['criminal'], 'B2', 78),
  ('burglary', 'noun', '/ˈbɜːɡləri/', 'проникнення зі зломом, крадіжка зі зломом', 'Entering a building illegally to steal.', 'The burglary happened while the family was away.', array['criminal'], 'B2', 79),
  ('assault', 'noun', '/əˈsɔːlt/', 'напад, побиття', 'An attack or threat of attack on a person.', 'He was charged with assault after the fight.', array['criminal','tort'], 'B2', 80),
  ('murder', 'noun', '/ˈmɜːdə/', 'вбивство', 'The unlawful killing of a person on purpose.', 'The suspect was accused of murder.', array['criminal'], 'B1', 81),
  ('manslaughter', 'noun', '/ˈmænslɔːtə/', 'ненавмисне вбивство', 'Unlawful killing without planning or intending to kill.', 'She was found guilty of manslaughter.', array['criminal'], 'C1', 82),
  ('bribery', 'noun', '/ˈbraɪbəri/', 'хабарництво', 'Offering or taking money to influence someone''s official actions.', 'The official was investigated for bribery.', array['criminal'], 'C1', 83),
  ('corruption', 'noun', '/kəˈrʌpʃn/', 'корупція', 'Dishonest or illegal behaviour by people in power.', 'The government promised to fight corruption.', array['criminal','public'], 'B2', 84),
  ('perjury', 'noun', '/ˈpɜːdʒəri/', 'лжесвідчення', 'Lying in court after promising to tell the truth.', 'He faced a charge of perjury.', array['criminal','evidence'], 'C1', 85),
  ('forgery', 'noun', '/ˈfɔːdʒəri/', 'підробка', 'Making a false document or signature to deceive.', 'The forgery was discovered by an expert.', array['criminal'], 'C1', 86),
  ('blackmail', 'noun', '/ˈblækmeɪl/', 'шантаж', 'Threatening to reveal secrets to force someone to pay or act.', 'She reported the blackmail to the police.', array['criminal'], 'B2', 87),
  ('arson', 'noun', '/ˈɑːsn/', 'підпал', 'The crime of deliberately setting fire to property.', 'The fire was caused by arson.', array['criminal'], 'C1', 88),
  ('suspect', 'noun', '/ˈsʌspekt/', 'підозрюваний', 'A person believed to have committed a crime.', 'The suspect was questioned for several hours.', array['criminal'], 'B1', 89),
  ('accused', 'noun', '/əˈkjuːzd/', 'обвинувачений', 'The person who is charged with a crime in court.', 'The accused pleaded not guilty.', array['criminal','procedure'], 'B2', 90),
  ('defendant', 'noun', '/dɪˈfendənt/', 'відповідач; підсудний', 'The person who is sued or charged in court.', 'The defendant denied all the allegations.', array['procedure','criminal'], 'B2', 91),
  ('plaintiff', 'noun', '/ˈpleɪntɪf/', 'позивач (США)', 'The person who brings a civil case to court.', 'The plaintiff claimed compensation for the injury.', array['procedure','tort'], 'B2', 92),
  ('prosecutor', 'noun', '/ˈprɒsɪkjuːtə/', 'прокурор, обвинувач', 'A lawyer who presents the case against the accused.', 'The prosecutor called three witnesses.', array['criminal','procedure'], 'B2', 93),
  ('prosecution', 'noun', '/ˌprɒsɪˈkjuːʃn/', 'кримінальне переслідування; сторона обвинувачення', 'The process of charging someone with a crime, or the side that does it.', 'The prosecution presented new evidence.', array['criminal','procedure'], 'B2', 94),
  ('charge', 'verb', '/tʃɑːdʒ/', 'висувати обвинувачення', 'To formally accuse someone of a crime.', 'Police charged him with fraud.', array['criminal'], 'B1', 95),
  ('arrest', 'verb', '/əˈrest/', 'заарештовувати, затримувати', 'To take a person into custody because of suspected crime.', 'They arrested the man at the airport.', array['criminal'], 'B1', 96),
  ('custody', 'noun', '/ˈkʌstədi/', 'тримання під вартою; опіка', 'Being held by police, or the legal right to care for a child.', 'The suspect remained in custody overnight.', array['criminal','family'], 'B2', 97),
  ('bail', 'noun', '/beɪl/', 'застава', 'Money paid to allow an accused person to stay free until trial.', 'The judge granted bail of five thousand pounds.', array['criminal','procedure'], 'B2', 98),
  ('warrant', 'noun', '/ˈwɒrənt/', 'ордер', 'An official paper allowing police to arrest or search.', 'Police obtained a warrant to search the house.', array['criminal','procedure'], 'B2', 99),
  ('search', 'noun', '/sɜːtʃ/', 'обшук', 'An official examination of a place or person for evidence.', 'The search of the car found no weapons.', array['criminal'], 'B1', 100),
  ('interrogation', 'noun', '/ɪnˌterəˈɡeɪʃn/', 'допит', 'Formal, intense questioning by police.', 'The interrogation lasted for six hours.', array['criminal'], 'C1', 101),
  ('confession', 'noun', '/kənˈfeʃn/', 'зізнання', 'A statement admitting guilt.', 'His confession was excluded as evidence.', array['criminal','evidence'], 'B2', 102),
  ('investigation', 'noun', '/ɪnˌvestɪˈɡeɪʃn/', 'розслідування', 'An official inquiry to discover the facts of a crime.', 'The investigation continued for two years.', array['criminal'], 'B2', 103),
  ('trial', 'noun', '/ˈtraɪəl/', 'судовий розгляд', 'A formal examination of a case in court.', 'The trial will begin next Monday.', array['procedure','criminal'], 'B1', 104),
  ('verdict', 'noun', '/ˈvɜːdɪkt/', 'вердикт', 'The decision of a jury about guilt or innocence.', 'The jury returned a verdict of not guilty.', array['procedure','criminal'], 'B2', 105),
  ('sentence', 'noun', '/ˈsentəns/', 'вирок, покарання', 'The punishment given by a court to a convicted person.', 'He received a sentence of five years in prison.', array['criminal'], 'B2', 106),
  ('convict', 'verb', '/kənˈvɪkt/', 'визнавати винним', 'To decide in court that someone is guilty of a crime.', 'The jury convicted her of fraud.', array['criminal'], 'B2', 107),
  ('conviction', 'noun', '/kənˈvɪkʃn/', 'обвинувальний вирок; судимість', 'A formal finding of guilt for a crime.', 'He has a previous conviction for theft.', array['criminal'], 'B2', 108),
  ('acquit', 'verb', '/əˈkwɪt/', 'виправдовувати', 'To decide in court that someone is not guilty.', 'The jury acquitted the defendant of all charges.', array['criminal'], 'C1', 109),
  ('acquittal', 'noun', '/əˈkwɪtl/', 'виправдувальний вирок', 'A court decision that a person is not guilty.', 'The acquittal surprised the public.', array['criminal'], 'C1', 110),
  ('guilty', 'adjective', '/ˈɡɪlti/', 'винний', 'Having committed a crime or offence.', 'The court found him guilty of theft.', array['criminal'], 'B1', 111),
  ('innocent', 'adjective', '/ˈɪnəsnt/', 'невинний', 'Not having committed a crime.', 'Everyone is presumed innocent until proven guilty.', array['criminal'], 'B1', 112),
  ('plea', 'noun', '/pliː/', 'заява про визнання/невизнання вини', 'A formal answer of guilty or not guilty to a charge.', 'He entered a plea of not guilty.', array['criminal','procedure'], 'B2', 113),
  ('parole', 'noun', '/pəˈrəʊl/', 'дострокове звільнення', 'Early release from prison under conditions.', 'The prisoner was granted parole after six years.', array['criminal'], 'C1', 114),
  ('probation', 'noun', '/prəˈbeɪʃn/', 'випробувальний термін, пробація', 'A period when an offender is supervised instead of being in prison.', 'She was sentenced to two years'' probation.', array['criminal'], 'C1', 115),
  ('imprisonment', 'noun', '/ɪmˈprɪznmənt/', 'позбавлення волі', 'The state of being put in prison.', 'The crime carries life imprisonment.', array['criminal'], 'B2', 116),
